def maxArea(height: list[int]) -> int:
    max_water = 0
    n = len(height)
    for i in range(n):
        for j in range(i + 1, n):
            current_water = min(height[i], height[j]) * (j - i)
            if current_water > max_water:
                max_water = current_water
    return max_water

